/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic d,
    output wire  q
);
    logic rise_sample_r;
    logic fall_sample_r;

    always_ff @(posedge clk)
        rise_sample_r <= d;

    always_ff @(negedge clk)
        fall_sample_r <= d;

    assign q = clk ? rise_sample_r : fall_sample_r;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 1'"'b0;
    logic d = 1'b0;
    wire q;
    logic expected;
    logic [15:0] prng = 16'h35ac;
    integer checks = 0;
    TopModule dut (.clk(clk), .d(d), .q(q));

    task automatic check_output;
        begin
            if (q "'!== expected)
                $fatal(1, "Mismatch clk=%b d=%b q=%b expected=%b", clk, d, q, expected);
            checks = checks + 1;
        end
    endtask

    task automatic sample_edge(input logic sample, input integer wait_ns);
        begin
            d = sample;
            #(wait_ns);
            expected = d;
            clk = ~clk;
            #1;
            check_output();
            d = ~sample;
            #1;
            check_output();
            d = sample;
            #1;
            check_output();
        end
    endtask

    initial begin
        // First capture is a rising edge; no assumption about power-up q.
        sample_edge(1'"'b0, 3);
        sample_edge(1'b0, 5);
        sample_edge(1'b1, 2);
        sample_edge(1'b1, 4);
        sample_edge(1'b0, 6);
        sample_edge(1'b1, 2);
        sample_edge(1'b1, 3);
        sample_edge(1'b0, 4);
        for (integer i = 0; i < 256; i = i + 1) begin
            prng = {prng[14:0], prng[15] "'^ prng[13] ''^ prng[12] ''^ prng[10]};
            sample_edge(prng[0], 2 + (i % 7));
        end
        $display("PASS: %0d capture/hold comparisons", checks);
        $finish;
    end

    initial begin
        #10000;
        $fatal(1, "Development watchdog timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim.vvp candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
if [ "$compile_status" -eq 0 ]; then
  timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim.vvp > dev_simulation.log 2>&1
  simulation_status=$?
  cat dev_simulation.log
else
  simulation_status=not_run
fi
printf '"'compile_exit=%s simulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > dev_status.log
cat dev_status.log'

